// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

// Test utilities - the foundation stones
const mockCart = {
  items: [{ id: '1', name: 'Wax Wings', price: 49.99 }],
  total: 49.99,
  clearCart: vi.fn(),
};

const mockPayment = {
  processPayment: vi.fn(),
};

const renderCheckout = (props = {}) => {
  return render(
    <CartProvider value={mockCart}>
      <PaymentProvider value={mockPayment}>
        <Checkout {...props} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - Happy Path', () => {
  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    mockPayment.processPayment.mockResolvedValue({ orderId: 'ORD-123' });

    renderCheckout({ onComplete });

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Crete Lane');
    await user.type(screen.getByLabelText(/city/i), 'Athens');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Daedalus');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/wax wings/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
    });
    expect(onComplete).toHaveBeenCalledWith('ORD-123');
  });
});

describe('Checkout - Validation', () => {
  it('shows error for invalid ZIP code', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue/i }));

    expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
    expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
  });
});

describe('Checkout - Edge Cases', () => {
  it('displays empty cart message when no items', () => {
    mockCart.items = [];
    renderCheckout();

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  it('handles payment failure gracefully', async () => {
    const user = userEvent.setup();
    mockPayment.processPayment.mockRejectedValue(new Error('Card declined'));

    // Navigate to review... then place order
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });
  });
});
